#!/usr/bin/env python3
"""Minimal agentic loop with Anthropic API, bash tool, and human confirmation."""

import os
import subprocess
import json
from typing import Dict, Any, Optional
from anthropic import Anthropic

class BashTool:
    """Tool for executing bash commands with confirmation."""

    def __init__(self):
        self.name = "run_bash"
        self.description = "Execute a bash command"

    def execute(self, command: str) -> Dict[str, Any]:
        """Execute bash command after user confirmation."""
        print(f"\n🔧 Tool request: {self.name}")
        print(f"Command: {command}")

        # Get user confirmation
        confirm = input("Execute this command? (y/n): ").lower().strip()
        if confirm != 'y':
            return {"output": "Command execution cancelled by user", "error": False}

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )
            return {
                "output": result.stdout or result.stderr,
                "error": result.returncode != 0,
                "return_code": result.returncode
            }
        except subprocess.TimeoutExpired:
            return {"output": "Command timed out after 30 seconds", "error": True}
        except Exception as e:
            return {"output": f"Error executing command: {str(e)}", "error": True}

class AgentLoop:
    """Minimal agentic loop using Anthropic API."""

    def __init__(self, api_key: Optional[str] = None):
        self.client = Anthropic(api_key=api_key or os.environ.get("ANTHROPIC_API_KEY"))
        self.tools = {
            "run_bash": BashTool()
        }
        self.conversation = []

    def get_tool_definitions(self):
        """Get tool definitions for Claude."""
        return [{
            "name": "run_bash",
            "description": "Execute a bash command on the system",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }]

    def process_tool_use(self, tool_use: Dict[str, Any]) -> Dict[str, Any]:
        """Process a tool use request from Claude."""
        tool_name = tool_use["name"]
        tool_input = tool_use["input"]

        if tool_name not in self.tools:
            return {"error": f"Unknown tool: {tool_name}"}

        tool = self.tools[tool_name]
        return tool.execute(**tool_input)

    def run(self, initial_prompt: str):
        """Run the agent loop."""
        print(f"🤖 Starting agent with prompt: {initial_prompt}\n")

        # Add initial user message
        self.conversation.append({
            "role": "user",
            "content": initial_prompt
        })

        while True:
            try:
                # Call Claude API
                response = self.client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=4096,
                    messages=self.conversation,
                    tools=self.get_tool_definitions(),
                    tool_choice={"type": "auto"}
                )

                # Add assistant message to conversation
                self.conversation.append({
                    "role": "assistant",
                    "content": response.content
                })

                # Process the response
                tool_uses = []
                text_content = []

                for content in response.content:
                    if content.type == "tool_use":
                        tool_uses.append(content)
                    elif content.type == "text":
                        text_content.append(content.text)

                # Print text response
                if text_content:
                    print(f"🤖 Claude: {' '.join(text_content)}")

                # Process tool uses
                if tool_uses:
                    tool_results = []

                    for tool_use in tool_uses:
                        result = self.process_tool_use(tool_use.model_dump())
                        tool_results.append({
                            "tool_use_id": tool_use.id,
                            "content": json.dumps(result)
                        })

                    # Add tool results to conversation
                    self.conversation.append({
                        "role": "user",
                        "content": tool_results
                    })

                    # Continue the loop to get Claude's response to tool results
                    continue

                # Check if task is complete
                complete = input("\n✅ Task complete? (y to exit, or type a new request): ").strip()
                if complete.lower() == 'y':
                    print("👋 Goodbye!")
                    break
                elif complete:
                    # New user request
                    self.conversation.append({
                        "role": "user",
                        "content": complete
                    })
                else:
                    print("👋 Goodbye!")
                    break

            except KeyboardInterrupt:
                print("\n👋 Interrupted! Goodbye!")
                break
            except Exception as e:
                print(f"❌ Error: {str(e)}")
                retry = input("Retry? (y/n): ").lower().strip()
                if retry != 'y':
                    break

def main():
    """Main entry point."""
    import sys

    # Check for API key
    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("❌ Error: ANTHROPIC_API_KEY environment variable not set")
        print("Please set it with: export ANTHROPIC_API_KEY='your-api-key'")
        sys.exit(1)

    # Get initial prompt from command line or ask user
    if len(sys.argv) > 1:
        initial_prompt = " ".join(sys.argv[1:])
    else:
        initial_prompt = input("🤔 What would you like help with? ")

    if not initial_prompt:
        print("❌ No prompt provided")
        sys.exit(1)

    # Run the agent loop
    agent = AgentLoop()
    agent.run(initial_prompt)

if __name__ == "__main__":
    main()

